const rawOutput = $input.first().json.stdout || '{}';
let data = {};
try {
  data = JSON.parse(rawOutput);
} catch (e) {
  throw new Error('Failed to parse yt-dlp JSON: ' + e.message);
}

const entries = data.entries || [];
const CHILD_REGEX = /\b(kids?|children|child|toddlers?|babies|baby|nursery|rhymes?|lullab(y|ies)|cocomelon|peppa|paw\s+patrol|bluey|blippi|chuchu|sesame\s+street|cartoons?\s+for\s+kids|toys?\s+review|preschool|sing-?along|abc\s+song)\b/i;
const AI_TECH_REGEX = /\b(ai|artificial intelligence|llm|gpt|claude|gemini|deepseek|agent|rag|prompt|cursor|coding|code|vibe coding|python|developer|robot|automation|copilot|ollama)\b/i;

const filtered = [];
for (const e of entries) {
  if (!e || !e.id) continue;
  const vid = String(e.id);
  const title = String(e.title || '');
  const channel = String(e.channel || e.uploader || '');
  const duration = parseFloat(e.duration) || 0;

  // Filter out music mixes & playlists
  if (vid.startsWith('RD') || e._type === 'playlist' || title.startsWith('Mix -') || title.startsWith('My Mix')) continue;

  // Filter out shorts (< 180s)
  if (duration < 180) continue;

  // Filter out child content
  if (e.is_kids || e.made_for_kids || CHILD_REGEX.test(title) || CHILD_REGEX.test(channel)) continue;

  const isAiTech = AI_TECH_REGEX.test(title + ' ' + channel);
  filtered.push({
    videoId: vid,
    title: title,
    channelName: channel,
    duration: duration,
    link: 'https://www.youtube.com/watch?v=' + vid,
    is_ai_tech: isAiTech
  });
}

// Prioritize AI/tech content
filtered.sort((a, b) => (b.is_ai_tech ? 1 : 0) - (a.is_ai_tech ? 1 : 0));

// Take top 5 candidates per run to conserve LLM budget
const candidates = filtered.slice(0, 5);
return candidates.map(c => ({ json: c }));

const videoInfo = $('3. Loop Over Video Candidates').first().json;
const transcriptData = JSON.parse($input.first().json.stdout || '{"transcript":""}');
const transcript = transcriptData.transcript || '';

return [{
  json: {
    videoId: videoInfo.videoId,
    title: videoInfo.title,
    channelName: videoInfo.channelName,
    link: videoInfo.link,
    duration: videoInfo.duration,
    transcript: transcript,
    has_transcript: transcript.length > 200
  }
}];

