const resp = $input.first().json;
const videoData = $('6. Has Valid Transcript?').first().json;
let parsed = { is_teachable_skill: false, skill_potential: 1 };

try {
  const text = resp.candidates[0].content.parts[0].text;
  parsed = JSON.parse(text);
} catch (e) {
  parsed.error = e.message;
}

return [{
  json: {
    ...videoData,
    evaluation: parsed,
    qualifies: parsed.is_teachable_skill && parsed.skill_potential >= 3
  }
}];

const item = $('9. Skill Qualifies (Potential >= 3)?').first().json;
return [{
  json: {
    status: 'staged',
    advisory: `[AIA-NEW-SKILL] Autonomous Harvester captured candidate: '${item.title}' from channel '${item.channelName}'. Potential: ${item.evaluation.skill_potential}/5. Staged in local vault for review.`,
    videoId: item.videoId,
    title: item.title
  }
}];
